CREATE COLUMN TABLE "TEST_AP"."OOCC" ("AbsEntry" INTEGER CS_INT NOT NULL , "Code" NVARCHAR(10) NOT NULL , "Dscription" NVARCHAR(128), "Note" NVARCHAR(50), "ReqBoeSt" NVARCHAR(1), "IsMovement" NVARCHAR(1) DEFAULT 'N' NOT NULL , PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OOCC_CODE" ON "TEST_AP"."OOCC" ( "Code" ASC, "IsMovement" ASC )